using System;using System.Collections.Generic;using System.IO;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
public static class DungeonDecorationShowcaseBuilder {
 public const string ScenePath="Assets/MapTests/DecorationShowcase.unity";const string Root="Assets/MapTests/DecorationShowcase";
 [MenuItem("Editor/Pruebas/Decoración del dungeon",false,2202)]public static void Open(){EditorSceneManager.OpenScene(ScenePath);}
 public static string Build(){if(File.Exists(ScenePath))return "Escena de prueba ya existe";Directory.CreateDirectory(Root);var map=ScriptableObject.CreateInstance<DungeonMapSettings>();map.includeLegacyObjects=false;map.startCell=new Vector2Int(3,1);int w=24,h=24;var rows=new char[h][];for(int y=0;y<h;y++){rows[y]=new char[w];for(int x=0;x<w;x++)rows[y][x]='#';}Action<int,int,int,int> carve=(a,b,c,d)=>{for(int y=b;y<=d;y++)for(int x=a;x<=c;x++)rows[y][x]='.';};carve(3,1,3,5);carve(3,5,9,5);carve(9,5,9,14);carve(6,15,19,21);map.rows=new string[h];for(int y=0;y<h;y++)map.rows[y]=new string(rows[y]);var entities=ScriptableObject.CreateInstance<DungeonEntitySettings>();entities.objects.Add(new DungeonMapEntity{id="decoration.test.door",kind=DungeonEntityKind.Door,cell=new Vector2Int(9,14),heading=0,doorInitiallyOpen=true,displayName="Sala de máquinas"});AssetDatabase.CreateAsset(entities,Root+"/Objects.asset");map.entities=entities;var regions=ScriptableObject.CreateInstance<DungeonRegionSettings>();regions.legacyPlacements=false;regions.initialRandomPerZone=0;var region=new DungeonRegion{id="decor.test",displayName="Laboratorio de ambientación",safeArea=true,spawnsEnabled=false};for(int y=0;y<h;y++)for(int x=0;x<w;x++)if(rows[y][x]=='.')region.cells.Add(new Vector2Int(x,y));regions.regions=new[]{region};AssetDatabase.CreateAsset(regions,Root+"/Regions.asset");map.regions=regions;
 var decor=ScriptableObject.CreateInstance<DungeonDecorationSettings>();decor.catalog=DungeonDecorationCatalog.Current;decor.regions=regions;string[] ids={"wall.crt","wall.vent","wall.pipe","wall.cable","wall.sign","wall.window","ceiling.light","ceiling.fan","room.server","room.arcade","room.column","room.generator","floor.circuit","floor.signal","door.frame"};Vector2Int[] cells={new Vector2Int(3,3),new Vector2Int(3,4),new Vector2Int(9,6),new Vector2Int(9,8),new Vector2Int(9,10),new Vector2Int(9,12),new Vector2Int(9,7),new Vector2Int(9,11),new Vector2Int(6,17),new Vector2Int(7,15),new Vector2Int(19,18),new Vector2Int(12,21),new Vector2Int(11,18),new Vector2Int(14,17),new Vector2Int(9,14)};int[] heads={3,1,3,1,3,1,0,0,3,2,1,0,0,0,0};for(int i=0;i<ids.Length;i++)decor.placements.Add(new DungeonDecorationPlacement{id="showcase."+i,prefabId=ids[i],cell=cells[i],heading=heads[i]});AssetDatabase.CreateAsset(decor,Root+"/Decorations.asset");map.decorations=decor;AssetDatabase.CreateAsset(map,Root+"/Map.asset");
 var scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);var root=new GameObject("Dungeon — prueba de decoración");var d=root.AddComponent<DungeonPrototype>();d.mapSettings=map;d.dungeonRegions=regions;root.AddComponent<DungeonDecorationShowcase>();new GameObject("Preview camera").AddComponent<Camera>();new GameObject("Preview light").AddComponent<Light>().type=LightType.Directional;AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(scene,ScenePath);return "Tres ejemplos creados con cámara real, región segura y guardado de prueba aislado";
 }
}
